import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const r="/rakkii-cars-guide/screenshots/12-finance-wallets-expenses-agent-fees-pnl-month-close-export/01-money-accounts.png",a="/rakkii-cars-guide/screenshots/12-finance-wallets-expenses-agent-fees-pnl-month-close-export/02-pnl.png",m=JSON.parse('{"title":"12. Finance: cash, money accounts, expenses, agent fees, P&L, month close & export","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/12-finance-wallets-expenses-agent-fees-pnl-month-close-export.md","filePath":"chapters/12-finance-wallets-expenses-agent-fees-pnl-month-close-export.md","lastUpdated":1793268728000}'),g={name:"chapters/12-finance-wallets-expenses-agent-fees-pnl-month-close-export.md"};function i(c,o,l,p,d,h){return e(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="_12-finance-cash-money-accounts-expenses-agent-fees-p-l-month-close-export" tabindex="-1">12. Finance: cash, money accounts, expenses, agent fees, P&amp;L, month close &amp; export <a class="header-anchor" href="#_12-finance-cash-money-accounts-expenses-agent-fees-p-l-month-close-export" aria-label="Permalink to &quot;12. Finance: cash, money accounts, expenses, agent fees, P&amp;L, month close &amp; export&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hub:</strong> Finance (<code>/finance</code>)</p><p>Receivables, payments, credit notes and storage are in <a href="/rakkii-cars-guide/chapters/08-lane-4-billing-chain-receivables-storage-credit-notes">Chapter 8</a>. Supplier payables are in <a href="/rakkii-cars-guide/chapters/09-parts-inventory-canvass-restock-payables">Chapter 9</a>.</p><h2 id="_12-1-cash-board-finance-cash" tabindex="-1">12.1 Cash board (<code>/finance/cash</code>) <a class="header-anchor" href="#_12-1-cash-board-finance-cash" aria-label="Permalink to &quot;12.1 Cash board (`/finance/cash`)&quot;">​</a></h2><p>The daily money view for the selected shop:</p><ul><li><strong>Today</strong> — <strong>Cash in today</strong>, <strong>Cash out today</strong>, <strong>Net cash today</strong>, <strong>Open AR</strong>, and supplier payables due soon / overdue.</li><li><strong>Cash in trend</strong> over recent days.</li><li><strong>Customer vs insurer AR</strong> and <strong>Aging</strong> buckets (bands from shop settings, default 30/60/90).</li><li><strong>Insurer cash coming in</strong> — insurance work <strong>Finished, not invoiced</strong> (bill it) and <strong>Authorized, not started</strong> (pipeline).</li></ul><h2 id="_12-2-money-accounts-finance-money-accounts" tabindex="-1">12.2 Money accounts (<code>/finance/money-accounts</code>) <a class="header-anchor" href="#_12-2-money-accounts-finance-money-accounts" aria-label="Permalink to &quot;12.2 Money accounts (`/finance/money-accounts`)&quot;">​</a></h2><p>The shop&#39;s wallets and bank accounts. Every customer payment, expense and transfer moves a balance. There is no bank or GCash statement import, so balances are only as good as what is recorded.</p><p>Default accounts: <strong>Cash on hand</strong>, <strong>GCash</strong>, <strong>Maya</strong>, <strong>Bank</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td><strong>Add account</strong></td><td><strong>Name</strong>, opening <strong>Balance</strong>, <strong>Note</strong></td></tr><tr><td><strong>Adjust</strong></td><td>Set the <strong>New balance</strong> after a real count, with a <strong>Reason</strong> (logged as an adjustment)</td></tr><tr><td><strong>Transfer</strong></td><td><strong>From</strong>, <strong>To</strong>, <strong>Amount</strong>, <strong>Date</strong>, <strong>Reference</strong>, <strong>Note</strong>. <strong>Void transfer</strong> reverses both sides</td></tr><tr><td><strong>Movements</strong></td><td>Every movement on the account; void a wrong one</td></tr><tr><td><strong>Update balances</strong></td><td>Recalculates from history (backfill)</td></tr></tbody></table><p><strong>End-of-day routine:</strong> count the cash drawer → compare with <strong>Cash on hand</strong> → <strong>Adjust</strong> with a reason if different → <strong>Transfer</strong> bank deposits from Cash on hand to Bank.</p><p><img src="'+r+'" alt="Money accounts with Transfer dialog"></p><h2 id="_12-3-expenses-finance-expenses" tabindex="-1">12.3 Expenses (<code>/finance/expenses</code>) <a class="header-anchor" href="#_12-3-expenses-finance-expenses" aria-label="Permalink to &quot;12.3 Expenses (`/finance/expenses`)&quot;">​</a></h2><ol><li>Press <strong>Add expense</strong>.</li><li>Fill <strong>Date</strong>, <strong>Amount</strong>, <strong>Category</strong> (from Company › Lists › Expense categories), <strong>Payee</strong>, <strong>Note</strong>.</li><li><strong>Paid from</strong> — the money account it comes out of (deducts the balance).</li><li>Optional <strong>Job</strong> — <strong>Find job</strong> to tie the cost to a job (it then counts in that job&#39;s P&amp;L); <strong>Clear job</strong> to unlink.</li><li><strong>Save</strong>.</li></ol><p>The page shows the month <strong>summary by category</strong> and the <strong>Log</strong>. <strong>Void</strong> an entry with a required reason (it stays visible as &quot;Voided · reason · by&quot; when <strong>Show voided</strong> is on). <strong>Export CSV</strong> or <strong>Print</strong>.</p><p>Some expenses are posted automatically: supplier payments (if <strong>Post supplier payments to expenses</strong> is on), backjob costs, contractor payouts, and paid agent fees (if <strong>Post agent fees to expenses</strong> is on).</p><h2 id="_12-4-agent-fees-finance-agent-fees" tabindex="-1">12.4 Agent fees (<code>/finance/agent-fees</code>) <a class="header-anchor" href="#_12-4-agent-fees-finance-agent-fees" aria-label="Permalink to &quot;12.4 Agent fees (`/finance/agent-fees`)&quot;">​</a></h2><p>The <strong>outside agent fee</strong> for referral agents who are not staff. It is separate from in-house sales commission (<a href="/rakkii-cars-guide/chapters/04-sales-agent-guide">Chapter 4</a>).</p><h3 id="set-the-fee-on-a-job" tabindex="-1">Set the fee on a job <a class="header-anchor" href="#set-the-fee-on-a-job" aria-label="Permalink to &quot;Set the fee on a job&quot;">​</a></h3><p>On the job&#39;s <strong>Pay</strong> tab, card <strong>Agent fee</strong>: choose the <strong>Mode</strong> (<strong>None</strong>, <strong>Percent</strong>, <strong>Fixed</strong>), the <strong>Value</strong> and <strong>Tax %</strong>. A rate above the shop default requires an <strong>Override reason</strong>.</p><h3 id="pay-agents" tabindex="-1">Pay agents <a class="header-anchor" href="#pay-agents" aria-label="Permalink to &quot;Pay agents&quot;">​</a></h3><ol><li>Pick the <strong>From</strong> / <strong>To</strong> range. The <strong>Agent</strong> table shows <strong>Referred</strong>, <strong>Approved amount</strong>, <strong>Agent comm pending</strong>, <strong>Due</strong> and <strong>Paid</strong> per agent, with the <strong>Referral fee total</strong>.</li><li>Open an agent to see each <strong>Job</strong>, <strong>Plate</strong>, <strong>Agent comm</strong>, <strong>SA comm</strong>, <strong>Status</strong> and <strong>Warnings</strong> (for example <strong>Agent comm required</strong> or <strong>Above default</strong>).</li><li>When a fee is due, press <strong>Pay</strong>: <strong>Paid date</strong>, <strong>Method</strong>, <strong>Reference</strong> (optional), <strong>Post to expenses</strong> → confirm.</li><li>A wrong fee is <strong>Void</strong>ed with a <strong>Reason</strong>. Voiding a paid fee also voids its referral-fee expense.</li></ol><p>Settings (<strong>Admin › Shop settings › Sales &amp; commission › Outside agent fee</strong>): <strong>Agent fee enabled</strong>, <strong>Default mode</strong> (None / Percent / Fixed) and value, <strong>Due when</strong> (<strong>Released</strong>, <strong>Customer paid</strong>, <strong>Immediately</strong>), <strong>Post agent fees to expenses</strong>, <strong>Walk-ins eligible</strong>.</p><h2 id="_12-5-reports-finance-reports" tabindex="-1">12.5 Reports (<code>/finance/reports</code>) <a class="header-anchor" href="#_12-5-reports-finance-reports" aria-label="Permalink to &quot;12.5 Reports (`/finance/reports`)&quot;">​</a></h2><ol><li>Choose the period: <strong>This month</strong>, <strong>Last month</strong>, <strong>This quarter</strong> or <strong>Custom</strong> (From / To).</li><li>Tiles: <strong>Work billed</strong> (before VAT), <strong>Cash collected</strong>, <strong>Expenses</strong>, <strong>Supplier payments</strong>, <strong>Net cash</strong>.</li><li>Tables: <strong>By job type</strong>, <strong>By payer</strong> (billed vs collected), <strong>Top insurers</strong>, <strong>Top fleet and corporate accounts</strong>, and <strong>Owed as of</strong> by aging bucket.</li><li><strong>Download CSV</strong>.</li></ol><h2 id="_12-6-profit-loss-finance-pnl-—-owner-only" tabindex="-1">12.6 Profit &amp; Loss (<code>/finance/pnl</code>) — owner only <a class="header-anchor" href="#_12-6-profit-loss-finance-pnl-—-owner-only" aria-label="Permalink to &quot;12.6 Profit &amp; Loss (`/finance/pnl`) — owner only&quot;">​</a></h2><p>Pick the month with the arrows.</p><p><strong>Monthly shop P&amp;L</strong> tab:</p><ul><li>Tiles: <strong>Revenue (net of VAT)</strong>, <strong>Direct job cost</strong>, <strong>Shop expenses</strong>, <strong>Commissions</strong>, <strong>Payroll</strong>, <strong>Net profit</strong>, <strong>Net margin</strong>.</li><li><strong>Statement</strong>: Revenue (posted invoices, net of VAT) − direct job costs (parts, labor, paint, fees) = <strong>Total direct job cost</strong> → less sales commissions = <strong>Gross profit</strong> → less shop expenses and gross payroll = <strong>Net profit</strong>.</li><li><strong>Expenses by category</strong>: Category, Entries, Total, % of expenses.</li></ul><p><strong>Job gross P&amp;L</strong> tab:</p><ul><li><strong>Revenue (net of VAT)</strong>, <strong>Gross profit</strong>, <strong>Gross margin</strong> and the <strong>Cost split</strong>.</li><li><strong>Margin by job</strong>: <strong>Job</strong>, <strong>Plate</strong>, <strong>Customer</strong>, <strong>Revenue (net of VAT)</strong>, <strong>Direct costs</strong>, <strong>Commissions</strong>, <strong>Total job cost</strong>, <strong>Gross profit</strong>, <strong>Margin %</strong>.</li></ul><p>Menu: <strong>Export shop P&amp;L (CSV)</strong>, <strong>Export job P&amp;L (CSV)</strong>, <strong>Print</strong>. This is a management report, not a BIR filing.</p><p><img src="'+a+'" alt="Monthly shop P&amp;L statement"></p><h2 id="_12-7-month-close-finance-month-close-—-owner-only" tabindex="-1">12.7 Month close (<code>/finance/month-close</code>) — owner only <a class="header-anchor" href="#_12-7-month-close-finance-month-close-—-owner-only" aria-label="Permalink to &quot;12.7 Month close (`/finance/month-close`) — owner only&quot;">​</a></h2><p>Locks a past month for the selected shop. Money records dated in a closed month cannot be changed; post corrections in the next open month.</p><ol><li>Pick the <strong>Year</strong>. Each month shows whether it is open or &quot;Closed by … on …&quot;.</li><li>After the month&#39;s checks (cash counted, expenses entered, payments recorded, payables reviewed, P&amp;L reviewed), press <strong>Close month</strong>.</li><li>If a correction must go into that month, the owner can <strong>Reopen</strong> it, fix, and close again.</li></ol><p><strong>Suggested monthly order:</strong> Payables → Expenses → Money accounts reconciled → Reports → P&amp;L → Accountant export → <strong>Close month</strong>.</p><h2 id="_12-8-accountant-export-finance-export" tabindex="-1">12.8 Accountant export (<code>/finance/export</code>) <a class="header-anchor" href="#_12-8-accountant-export-finance-export" aria-label="Permalink to &quot;12.8 Accountant export (`/finance/export`)&quot;">​</a></h2><ol><li>Set <strong>From</strong> and <strong>To</strong>.</li><li><strong>Invoice status</strong>: <strong>All, incl. void</strong> or <strong>Posted only</strong>.</li><li>Choose the report: <strong>Invoices</strong>, <strong>Payments</strong>, <strong>Credit notes</strong> or <strong>Open AR</strong>, and download the CSV.</li><li><strong>Download open AR (CSV)</strong> gives the receivables list as of today.</li></ol><p>Send the files to the bookkeeper or accountant for BIR filing.</p>',40)])])}const u=t(g,[["render",i]]);export{m as __pageData,u as default};
